// 视频导出文件名的纯计算。

import type { VideoExportPreferences } from './settings';

type VideoContent = VideoExportPreferences['content'];

/** 用当前起始场景名作为文件名, 并按导出内容选择扩展名。 */
export function outputNameForScene(scene: string, content: VideoContent): string {
  const stem = scene.replace(/\.txt$/i, '') || scene;
  return `${stem}${content === 'audio' ? '.wav' : '.mp4'}`;
}

/** 在重名文件名的扩展名前追加递增编号。 */
export function numberedOutputName(name: string, index: number): string {
  const dot = name.lastIndexOf('.');
  const stem = dot > 0 ? name.slice(0, dot) : name;
  const extension = dot > 0 ? name.slice(dot) : '';
  return `${stem} (${index})${extension}`;
}
